import {useState} from 'react';
export default function ImageUpload({label,name,value=''}){const [data,setData]=useState(value),[error,setError]=useState('');return <label className="field"><span>{label}</span>{data?<img className="upload-preview" src={data} alt={`${label} preview`}/>:null}<input type="hidden" name={name} value={data}/><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{const file=e.target.files[0];if(!file)return;setError('');try{if(file.size>10*1024*1024)throw Error('Choose an image under 10 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');const scale=Math.min(1,240/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let encoded=canvas.toDataURL('image/jpeg',0.72);if(encoded.length>24000)encoded=canvas.toDataURL('image/jpeg',0.35);if(encoded.length>24000)throw Error('Please choose a simpler image.');setData(encoded);}catch(err){setError(err.message);}}}/>{data?<button type="button" className="text-button" onClick={()=>setData('')}>Remove image</button>:null}{error?<span role="alert" className="error">{error}</span>:null}</label>;}
